    String a = "6.1.0";
    String b = "6.1.0rc3";
    // this is the unusual version string, with 'H' in the middle
    String c = "6.1H.5-beta";
    // classical
    checkVersionsOrder(b, a);
    // now b < c, but before MNG-5568, we had b > c
    checkVersionsOrder(b, c);
