@Test
void cancellation() throws InterruptedException {
    TransferListener delegate = new TransferListener() {

        @Override
        public void transferInitiated(TransferEvent event) throws TransferCancelledException {
            throw new TransferCancelledException();
        }

        @Override
        public void transferStarted(TransferEvent event) throws TransferCancelledException {
            throw new TransferCancelledException();
        }

        @Override
        public void transferProgressed(TransferEvent event) throws TransferCancelledException {
            throw new TransferCancelledException();
        }

        @Override
        public void transferCorrupted(TransferEvent event) throws TransferCancelledException {
            throw new TransferCancelledException();
        }

        @Override
        public void transferSucceeded(TransferEvent event) {
        }

        @Override
        public void transferFailed(TransferEvent event) {
        }
    };
    try (SimplexTransferListener listener = new SimplexTransferListener(delegate)) {
        TransferResource resource = new TransferResource(null, null, "http://maven.org/test/test-resource", new File("file"), null);
        // no close handle
        DefaultRepositorySystemSession session = new DefaultRepositorySystemSession(h -> false);
        // for technical reasons we cannot throw here, even if delegate does cancel transfer
        listener.transferInitiated(event(session, resource, TransferEvent.EventType.INITIATED));
        // to make sure queue is processed, cancellation applied
        Thread.sleep(500);
        // subsequent call will cancel
        assertThrows(TransferCancelledException.class, () -> listener.transferStarted(event(session, resource, TransferEvent.EventType.STARTED)));
    }
}

@Test
void handlesAbsentTransferSource() throws InterruptedException, TransferCancelledException {
    TransferResource resource = new TransferResource(null, null, "http://maven.org/test/test-resource", null, null);
    RepositorySystemSession session = Mockito.mock(RepositorySystemSession.class);
    TransferListener delegate = Mockito.mock(TransferListener.class);
    try (SimplexTransferListener listener = new SimplexTransferListener(delegate)) {
        TransferEvent transferInitiatedEvent = event(session, resource, TransferEvent.EventType.INITIATED);
        TransferEvent transferStartedEvent = event(session, resource, TransferEvent.EventType.STARTED);
        TransferEvent transferProgressedEvent = event(session, resource, TransferEvent.EventType.PROGRESSED);
        TransferEvent transferSucceededEvent = event(session, resource, TransferEvent.EventType.SUCCEEDED);
        listener.transferInitiated(transferInitiatedEvent);
        listener.transferStarted(transferStartedEvent);
        listener.transferProgressed(transferProgressedEvent);
        listener.transferSucceeded(transferSucceededEvent);
        // to make sure queue is processed, cancellation applied
        Thread.sleep(500);
        Mockito.verify(delegate).transferInitiated(transferInitiatedEvent);
        Mockito.verify(delegate).transferStarted(transferStartedEvent);
        Mockito.verify(delegate).transferProgressed(transferProgressedEvent);
        Mockito.verify(delegate).transferSucceeded(transferSucceededEvent);
    }
}

@Test
@SuppressWarnings("checkstyle:UnusedLocalVariable")
void testAptConsistency() throws Exception {
    File apt = getTestFile("src/site/apt/artifact-handlers.apt");
    List<String> lines = Files.readAllLines(apt.toPath());
    for (String line : lines) {
        if (line.startsWith("||")) {
            String[] cols = line.split("\\|\\|");
            String[] expected = new String[] { "", "type", "classifier", "extension", "packaging", "language", "added to classpath", "includesDependencies", "" };
            int i = 0;
            for (String col : cols) {
                assertEquals(expected[i++], col.trim(), "Wrong column header");
            }
        } else if (line.startsWith("|")) {
            String[] cols = line.split("\\|");
            String type = trimApt(cols[1]);
            String classifier = trimApt(cols[2]);
            String extension = trimApt(cols[3], type);
            String packaging = trimApt(cols[4], type);
            String language = trimApt(cols[5]);
            String addedToClasspath = trimApt(cols[6]);
            String includesDependencies = trimApt(cols[7]);
            ArtifactHandler handler = container.lookup(ArtifactHandlerManager.class).getArtifactHandler(type);
            assertEquals(handler.getExtension(), extension, type + " extension");
            // Packaging/Directory is Maven1 remnant!!!
            // assertEquals(handler.getPackaging(), packaging, type + " packaging");
            assertEquals(handler.getClassifier(), classifier, type + " classifier");
            assertEquals(handler.getLanguage(), language, type + " language");
            assertEquals(handler.isAddedToClasspath() ? "true" : null, addedToClasspath, type + " addedToClasspath");
            assertEquals(handler.isIncludesDependencies() ? "true" : null, includesDependencies, type + " includesDependencies");
        }
    }
}

