@Test
void transportConfigurationTest() throws InvalidRepositoryException {
    DefaultRepositorySystemSessionFactory systemSessionFactory = new DefaultRepositorySystemSessionFactory(aetherRepositorySystem, eventSpyDispatcher, information, defaultTypeRegistry, versionScheme, Collections.emptyMap());
    MavenExecutionRequest request = new DefaultMavenExecutionRequest();
    request.setLocalRepository(getLocalRepository());
    // native
    Properties properties = new Properties();
    properties.setProperty("maven.resolver.transport", "apache");
    request.setSystemProperties(properties);
    Map<String, Object> configProperties = systemSessionFactory.newRepositorySession(request).getConfigProperties();
    assertEquals(String.valueOf(Float.MAX_VALUE), configProperties.get("aether.priority.FileTransporterFactory"));
    assertEquals(String.valueOf(Float.MAX_VALUE), configProperties.get("aether.priority.ApacheTransporterFactory"));
    properties.remove("maven.resolver.transport");
    // wagon
    properties.setProperty("maven.resolver.transport", "wagon");
    request.setSystemProperties(properties);
    assertEquals(String.valueOf(Float.MAX_VALUE), systemSessionFactory.newRepositorySession(request).getConfigProperties().get("aether.priority.WagonTransporterFactory"));
    properties.remove("maven.resolver.transport");
    // illegal
    properties.setProperty("maven.resolver.transport", "illegal");
    request.setSystemProperties(properties);
    IllegalArgumentException exception = assertThrowsExactly(IllegalArgumentException.class, () -> systemSessionFactory.newRepositorySession(request));
    assertEquals("Unknown resolver transport 'illegal'. Supported transports are: wagon, apache, jdk, auto", exception.getMessage());
    properties.remove("maven.resolver.transport");
}

@Test
void versionFilteringTest() throws InvalidRepositoryException {
    DefaultRepositorySystemSessionFactory systemSessionFactory = new DefaultRepositorySystemSessionFactory(aetherRepositorySystem, eventSpyDispatcher, information, defaultTypeRegistry, versionScheme, Collections.emptyMap());
    MavenExecutionRequest request = new DefaultMavenExecutionRequest();
    request.setLocalRepository(getLocalRepository());
    VersionFilter versionFilter;
    // single one
    request.getUserProperties().put("maven.session.versionFilter", "s");
    versionFilter = systemSessionFactory.newRepositorySession(request).getVersionFilter();
    assertNotNull(versionFilter);
    assertInstanceOf(ContextualSnapshotVersionFilter.class, versionFilter);
    request.getUserProperties().put("maven.session.versionFilter", "h");
    versionFilter = systemSessionFactory.newRepositorySession(request).getVersionFilter();
    assertNotNull(versionFilter);
    assertInstanceOf(HighestVersionFilter.class, versionFilter);
    request.getUserProperties().put("maven.session.versionFilter", "h(5)");
    versionFilter = systemSessionFactory.newRepositorySession(request).getVersionFilter();
    assertNotNull(versionFilter);
    assertInstanceOf(HighestVersionFilter.class, versionFilter);
    request.getUserProperties().put("maven.session.versionFilter", "l");
    versionFilter = systemSessionFactory.newRepositorySession(request).getVersionFilter();
    assertNotNull(versionFilter);
    assertInstanceOf(LowestVersionFilter.class, versionFilter);
    request.getUserProperties().put("maven.session.versionFilter", "l(5)");
    versionFilter = systemSessionFactory.newRepositorySession(request).getVersionFilter();
    assertNotNull(versionFilter);
    assertInstanceOf(LowestVersionFilter.class, versionFilter);
    request.getUserProperties().put("maven.session.versionFilter", "e(g:a:v)");
    versionFilter = systemSessionFactory.newRepositorySession(request).getVersionFilter();
    assertNotNull(versionFilter);
    assertInstanceOf(PredicateVersionFilter.class, versionFilter);
    request.getUserProperties().put("maven.session.versionFilter", "e(g:a:[1,2])");
    versionFilter = systemSessionFactory.newRepositorySession(request).getVersionFilter();
    assertNotNull(versionFilter);
    assertInstanceOf(PredicateVersionFilter.class, versionFilter);
    // chained
    request.getUserProperties().put("maven.session.versionFilter", "h(5);s;e(org.foo:bar:1)");
    versionFilter = systemSessionFactory.newRepositorySession(request).getVersionFilter();
    assertNotNull(versionFilter);
    assertInstanceOf(ChainedVersionFilter.class, versionFilter);
}

