@Test
void testGraph() throws Exception {
    ProjectBuildList projectBuildList = ProjectDependencyGraphStub.getProjectBuildList(ProjectDependencyGraphStub.getMavenSession());
    ProjectDependencyGraph projectDependencyGraph = new ProjectDependencyGraphStub();
    ConcurrencyDependencyGraph graph = new ConcurrencyDependencyGraph(projectBuildList, projectDependencyGraph);
    // start
    assertEquals(0, graph.getFinishedProjects().size());
    assertEquals(6, graph.getNumberOfBuilds());
    List<MavenProject> rootSchedulableBuilds = graph.getRootSchedulableBuilds();
    // only Project.A has no dependencies
    assertEquals(1, rootSchedulableBuilds.size());
    assertEquals(ProjectDependencyGraphStub.A, rootSchedulableBuilds.iterator().next());
    // double check A deps
    List<MavenProject> dependenciesA = graph.getDependencies(ProjectDependencyGraphStub.A);
    assertEquals(0, dependenciesA.size());
    assertEquals(6, graph.getUnfinishedProjects().size());
    List<MavenProject> schedulableNewProcesses = graph.markAsFinished(ProjectDependencyGraphStub.A);
    // expect Project B, C
    assertEquals(2, schedulableNewProcesses.size());
    assertEquals(1, graph.getFinishedProjects().size());
    graph.markAsFinished(ProjectDependencyGraphStub.A);
    // still only  A
    assertEquals(1, graph.getFinishedProjects().size());
    Set<MavenProject> unfinishedProjects = graph.getUnfinishedProjects();
    assertEquals(5, unfinishedProjects.size());
    graph.markAsFinished(schedulableNewProcesses.get(0));
    assertEquals(2, graph.getFinishedProjects().size());
    assertEquals(4, graph.getUnfinishedProjects().size());
    List<MavenProject> dependenciesC = graph.getDependencies(ProjectDependencyGraphStub.C);
    // C depends only on A
    assertEquals(1, dependenciesC.size());
    List<MavenProject> dependenciesX = graph.getDependencies(ProjectDependencyGraphStub.X);
    // X depends only on B and C
    assertEquals(2, dependenciesX.size());
    List<MavenProject> activeDependenciesC = graph.getActiveDependencies(ProjectDependencyGraphStub.C);
    // A already finished
    assertEquals(0, activeDependenciesC.size());
    List<MavenProject> activeDependenciesX = graph.getActiveDependencies(ProjectDependencyGraphStub.X);
    // waiting for C
    assertEquals(1, activeDependenciesX.size());
}

@Test
void testProjectWeightCalculation() {
    // Test that projects with longer downstream chains get higher weights
    // Graph: A -> B,C; B -> X,Y; C -> X,Z
    MavenProject projectA = ProjectDependencyGraphStub.A;
    MavenProject projectB = ProjectDependencyGraphStub.B;
    MavenProject projectC = ProjectDependencyGraphStub.C;
    MavenProject projectX = ProjectDependencyGraphStub.X;
    long weightA = comparator.getProjectWeight(projectA);
    long weightB = comparator.getProjectWeight(projectB);
    long weightC = comparator.getProjectWeight(projectC);
    long weightX = comparator.getProjectWeight(projectX);
    // Project A should have the highest weight as it's at the root
    assertTrue(weightA > weightB, "Project A should have weight > Project B");
    assertTrue(weightA > weightC, "Project A should have weight > Project C");
    assertTrue(weightB > weightX, "Project B should have weight > Project X");
    assertTrue(weightC > weightX, "Project C should have weight > Project X");
}

@Test
void testComparatorOrdering() {
    List<MavenProject> projects = Arrays.asList(ProjectDependencyGraphStub.X, ProjectDependencyGraphStub.C, ProjectDependencyGraphStub.A, ProjectDependencyGraphStub.B);
    // Sort using the comparator
    projects.sort(comparator.getComparator());
    // Project A should come first (highest weight)
    assertEquals(ProjectDependencyGraphStub.A, projects.get(0), "Project A should be first (highest critical path weight)");
    // B and C should come before X (they have higher weights)
    assertTrue(projects.indexOf(ProjectDependencyGraphStub.B) < projects.indexOf(ProjectDependencyGraphStub.X), "Project B should come before X");
    assertTrue(projects.indexOf(ProjectDependencyGraphStub.C) < projects.indexOf(ProjectDependencyGraphStub.X), "Project C should come before X");
}

