    // In the stub: A -> B,C; B -> X,Y; C -> X,Z
    long weightA = comparator.getProjectWeight(ProjectDependencyGraphStub.A);
    long weightB = comparator.getProjectWeight(ProjectDependencyGraphStub.B);
