    List<Plugin> plugins = project.getBuildPlugins();
    // Plugin0 [plexus]
    String key = "org.apache.maven.plugins:maven-plexus-plugin";
    Plugin plugin = null;
    for (Plugin check : plugins) {
        if (key.equals(check.getKey())) {
            plugin = check;
            break;
        }
    }
    assertNotNull(plugin);
    assertEquals("1.0", plugin.getVersion());
    XmlNode configuration = plugin.getDelegate().getConfiguration();
    assertEquals("src/conf/plexus.conf", configuration.child("plexusConfiguration").value());
    assertEquals("src/conf/plexus.properties", configuration.child("plexusConfigurationPropertiesFile").value());
    assertEquals("Continuum", configuration.child("plexusApplicationName").value());
    // ----------------------------------------------------------------------
    // Goal specific configuration
    // ----------------------------------------------------------------------
    List<PluginExecution> executions = plugin.getExecutions();
    PluginExecution execution = executions.get(0);
    String g0 = execution.getGoals().get(0);
    assertEquals("plexus:runtime", g0);
    configuration = execution.getDelegate().getConfiguration();
    assertEquals("ContinuumPro", configuration.child("plexusApplicationName").value());
