        assertTrue(project.getInjectedProfileIds().get(project.getId()).stream().noneMatch("profile1"::equals));
        assertTrue(project.getInjectedProfileIds().get(project.getId()).stream().noneMatch("profile2"::equals));
        assertTrue(project.getInjectedProfileIds().get(project.getId()).stream().anyMatch("active-by-default"::equals));
        InternalMavenSession session = Mockito.mock(InternalMavenSession.class);
        List<org.apache.maven.api.model.Profile> activeProfiles = new DefaultProject(session, project).getDeclaredActiveProfiles();
        assertEquals(2, activeProfiles.size());
        org.apache.maven.api.model.Profile profile = activeProfiles.get(0);
        assertEquals("active-by-default", profile.getId());
        InputLocation location = profile.getLocation("");
        assertNotNull(location, "Profile location should not be null for profile: " + profile.getId());
        assertTrue(location.getLineNumber() > 0, "Profile location line number should be positive, but was: " + location.getLineNumber() + " for profile: " + profile.getId());
        assertTrue(location.getColumnNumber() > 0, "Profile location column number should be positive, but was: " + location.getColumnNumber() + " for profile: " + profile.getId());
        assertNotNull(location.getSource(), "Profile location source should not be null for profile: " + profile.getId());
        assertTrue(location.getSource().getLocation().contains("pom-with-profiles/pom.xml"), "Profile location should contain 'pom-with-profiles/pom.xml', but was: " + location.getSource().getLocation() + " for profile: " + profile.getId());
        // This demonstrates the cross-platform path behavior for the POM file
        String actualLocation = location.getSource().getLocation();
        String expectedPath = "pom-with-profiles" + separator + "pom.xml";
        // The test will pass with File.separator but this shows the platform differences
        assertTrue(actualLocation.contains("pom-with-profiles/pom.xml"), "Location should contain path with proper separators for " + fsName + " (actual: " + actualLocation + ")\n" + "=== Cross-Platform Path Test [" + fsName + "] - External Profile ===\n" + "Expected path pattern: " + expectedPath + "\n" + "Actual location: " + actualLocation + "\n" + "Contains expected pattern: " + actualLocation.contains(expectedPath) + "\n" + "File.separator on this system: '" + File.separator + "'");
        profile = activeProfiles.get(1);
        assertEquals("external-profile", profile.getId());
        location = profile.getLocation("");
        assertNotNull(location, "External profile location should not be null for profile: " + profile.getId());
        assertTrue(location.getLineNumber() > 0, "External profile location line number should be positive, but was: " + location.getLineNumber() + " for profile: " + profile.getId());
        assertTrue(location.getColumnNumber() > 0, "External profile location column number should be positive, but was: " + location.getColumnNumber() + " for profile: " + profile.getId());
        assertNotNull(location.getSource(), "External profile location source should not be null for profile: " + profile.getId());
        assertTrue(location.getSource().getLocation().contains("settings.xml"), "External profile location should contain 'settings.xml', but was: " + location.getSource().getLocation() + " for profile: " + profile.getId());
    }
}

