@Test
void testBuildPluginInterpolation() throws Exception {
    PomTestWrapper pom = buildPom("plugin-interpolation-build", "activeProfile");
    Model originalModel = pom.getMavenProject().getOriginalModel();
    // =============================================
    assertEquals("||${project.basedir}||", originalModel.getProperties().get("prop-outside"));
    List<Plugin> outsidePlugins = originalModel.getBuild().getPlugins();
    assertEquals(1, outsidePlugins.size());
    checkBuildPluginWithArtifactId(outsidePlugins, "plugin-all-profiles", "Outside ||${project.basedir}||", "<plugin-all-profiles-out>Outside ||${project.basedir}||</plugin-all-profiles-out>");
    // =============================================
    Profile activeProfile = originalModel.getProfiles().stream().filter(profile -> profile.getId().equals("activeProfile")).findFirst().orElse(null);
    assertNotNull(activeProfile, "Unable to find the activeProfile");
    assertTrue(isActiveProfile(pom.getMavenProject(), activeProfile), "The activeProfile should be active in the maven project");
    assertEquals("||${project.basedir}||", activeProfile.getProperties().get("prop-active"));
    List<Plugin> activeProfilePlugins = activeProfile.getBuild().getPlugins();
    assertEquals(2, activeProfilePlugins.size(), "Number of active profile plugins");
    checkBuildPluginWithArtifactId(activeProfilePlugins, "plugin-all-profiles", "Active all ||${project.basedir}||", "<plugin-all-profiles-in>Active all ||${project.basedir}||</plugin-all-profiles-in>");
    checkBuildPluginWithArtifactId(activeProfilePlugins, "only-active-profile", "Active only ||${project.basedir}||", "<plugin-in-active-profile-only>Active only ||${project.basedir}||</plugin-in-active-profile-only>");
    // =============================================
    Profile inactiveProfile = originalModel.getProfiles().stream().filter(profile -> profile.getId().equals("inactiveProfile")).findFirst().orElse(null);
    assertNotNull(inactiveProfile, "Unable to find the inactiveProfile");
    assertFalse(isActiveProfile(pom.getMavenProject(), inactiveProfile), "The inactiveProfile should NOT be active in the maven project");
    assertEquals("||${project.basedir}||", inactiveProfile.getProperties().get("prop-inactive"));
    List<Plugin> inactiveProfilePlugins = inactiveProfile.getBuild().getPlugins();
    assertEquals(2, inactiveProfilePlugins.size(), "Number of active profile plugins");
    checkBuildPluginWithArtifactId(inactiveProfilePlugins, "plugin-all-profiles", "Inactive all ||${project.basedir}||", "<plugin-all-profiles-ina>Inactive all ||${project.basedir}||</plugin-all-profiles-ina>");
    checkBuildPluginWithArtifactId(inactiveProfilePlugins, "only-inactive-profile", "Inactive only ||${project.basedir}||", "<plugin-in-inactive-only>Inactive only ||${project.basedir}||</plugin-in-inactive-only>");
}

