    // modify parent
    File parent = new File(tempDir.toFile(), "pom.xml");
    String parentContent = new String(Files.readAllBytes(parent.toPath()), StandardCharsets.UTF_8);
    parentContent = parentContent.replace("<packaging>pom</packaging>", "<packaging>pom</packaging><properties><addedProperty>addedValue</addedProperty></properties>");
