    Resource customResource = resources.stream().filter(r -> r.getDirectory().endsWith("custom")).findFirst().orElseThrow(() -> new AssertionError("Custom resource not found"));
    // Verify targetPath was preserved through conversion chain
    assertEquals("custom-output", customResource.getTargetPath(), "targetPath should be preserved in ConnectedResource");
