public void testSimplifyType() {
    {
        Type type = Integer.class;
        assertEquals(type, simplifyType(type));
    }
    {
        Type type = new Key<Set<Integer>>() {
        }.getType();
        assertEquals(type, simplifyType(type));
    }
    {
        Type type = new Key<Set<Set<Set<Integer>>>>() {
        }.getType();
        assertEquals(type, simplifyType(type));
    }
    {
        Type type = new Key<Set<? extends Integer>>() {
        }.getType();
        Type expected = new Key<Set<Integer>>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<Set<? extends Set<? extends Set<? extends Integer>>>>() {
        }.getType();
        Type expected = new Key<Set<Set<Set<Integer>>>>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<Set<Set<? extends Set<Integer>>>>() {
        }.getType();
        Type expected = new Key<Set<Set<Set<Integer>>>>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<Set<? super Integer>>() {
        }.getType();
        Type expected = new Key<Set<Integer>>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<Set<? super Set<? super Set<? super Integer>>>>() {
        }.getType();
        Type expected = new Key<Set<Set<Set<Integer>>>>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<Set<Set<? super Set<Integer>>>>() {
        }.getType();
        Type expected = new Key<Set<Set<Set<Integer>>>>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<Set<? extends Set<? super Set<? extends Integer>>>>() {
        }.getType();
        Type expected = new Key<Set<Set<Set<Integer>>>>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<Set<? extends Integer>[]>() {
        }.getType();
        Type expected = new Key<Set<Integer>[]>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<Set<? super Integer>[]>() {
        }.getType();
        Type expected = new Key<Set<Integer>[]>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<TestInterface<? extends Integer, ? extends Integer>>() {
        }.getType();
        Type expected = new Key<TestInterface<Integer, Integer>>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<TestInterface<Integer, Integer>>() {
        }.getType();
        Type expected = new Key<TestInterface<Integer, Integer>>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<TestClass<?, ?, ?, ?, ?, ?, ?, ?, ?>>() {
        }.getType();
        Type expected = TestClass.class;
        assertEquals(expected, simplifyType(type));
    }
    {
        Type type = new Key<TestClass<?, ?, ?, Object, ?, ?, ?, ?, ?>>() {
        }.getType();
        Type expected = TestClass.class;
        assertEquals(expected, simplifyType(type));
    }
    {
        //noinspection TypeParameterExplicitlyExtendsObject
        Type type = new Key<TestClass<Integer, ? extends Integer, ? super Integer, Object, ? extends Object, ? super Object, ?, Set<? extends TestInterface<Integer, ? extends Integer>>, Set<? super TestInterface<Integer, ? super Integer>>>>() {
        }.getType();
        Type expected = new Key<TestClass<Integer, Integer, Integer, Object, Object, Object, Object, Set<TestInterface<Integer, Integer>>, Set<TestInterface<Integer, Integer>>>>() {
        }.getType();
        assertEquals(expected, simplifyType(type));
    }
}

