@Test
public void testMergeRepositories() throws Exception {
    // this is here only to trigger mainSession creation; unrelated
    ModelBuilderRequest request = ModelBuilderRequest.builder().session(session).userProperties(Map.of("firstParentRepo", "https://some.repo")).requestType(ModelBuilderRequest.RequestType.BUILD_PROJECT).source(Sources.buildSource(getPom("props-and-profiles"))).build();
    ModelBuilder.ModelBuilderSession session = builder.newSession();
    // ignored result value; just to trigger mainSession creation
    session.build(request);
    Field mainSessionField = DefaultModelBuilder.ModelBuilderSessionImpl.class.getDeclaredField("mainSession");
    mainSessionField.setAccessible(true);
    DefaultModelBuilder.ModelBuilderSessionState state = (DefaultModelBuilder.ModelBuilderSessionState) mainSessionField.get(session);
    Field repositoriesField = DefaultModelBuilder.ModelBuilderSessionState.class.getDeclaredField("repositories");
    repositoriesField.setAccessible(true);
    List<RemoteRepository> repositories;
    // before merge
    repositories = (List<RemoteRepository>) repositoriesField.get(state);
    // central
    assertEquals(1, repositories.size());
    Model model = Model.newBuilder().properties(Map.of("thirdParentRepo", "https://third.repo")).repositories(Arrays.asList(Repository.newBuilder().id("first").url("${firstParentRepo}").build(), Repository.newBuilder().id("second").url("${secondParentRepo}").build(), Repository.newBuilder().id("third").url("${thirdParentRepo}").build())).build();
    state.mergeRepositories(model, false);
    // after merge
    repositories = (List<RemoteRepository>) repositoriesField.get(state);
    assertEquals(4, repositories.size());
    assertEquals("first", repositories.get(0).getId());
    // interpolated (user properties)
    assertEquals("https://some.repo", repositories.get(0).getUrl());
    assertEquals("second", repositories.get(1).getId());
    // un-interpolated (no source)
    assertEquals("${secondParentRepo}", repositories.get(1).getUrl());
    assertEquals("third", repositories.get(2).getId());
    // interpolated (own model properties)
    assertEquals("https://third.repo", repositories.get(2).getUrl());
    // default
    assertEquals("central", repositories.get(3).getId());
}

