void testTraces() {
    Path localRepo = System.getProperty("localRepository") != null ? Path.of(System.getProperty("localRepository")) : null;
    Session session = ApiRunner.createSession(injector -> {
        injector.bindInstance(RequestTraceTest.class, this);
    }, localRepo);
    ModelBuilder builder = session.getService(ModelBuilder.class);
    ModelBuilderResult result = builder.newSession().build(ModelBuilderRequest.builder().session(session).source(Sources.buildSource(Paths.get("pom.xml").toAbsolutePath())).requestType(ModelBuilderRequest.RequestType.BUILD_PROJECT).recursive(true).build());
    assertNotNull(result.getEffectiveModel());
    List<RepositoryEvent> events = new CopyOnWriteArrayList<>();
    ((DefaultRepositorySystemSession) InternalSession.from(session).getSession()).setRepositoryListener(new AbstractRepositoryListener() {

        @Override
        public void artifactResolved(RepositoryEvent event) {
            events.add(event);
        }
    });
    ArtifactCoordinates coords = session.createArtifactCoordinates("org.apache.maven:maven-api-core:4.0.0-alpha-13");
    DownloadedArtifact res = session.resolveArtifact(coords);
    assertNotNull(res);
    assertNotNull(res.getPath());
    assertTrue(Files.exists(res.getPath()));
    Node node = session.getService(DependencyResolver.class).collect(DependencyResolverRequest.builder().trace(new RequestTrace("collect", null, null)).session(session).requestType(DependencyResolverRequest.RequestType.COLLECT).dependency(session.createDependencyCoordinates(coords)).pathScope(PathScope.MAIN_RUNTIME).build()).getRoot().getChildren().iterator().next();
    for (RepositoryEvent event : events) {
        org.eclipse.aether.RequestTrace trace = event.getTrace();
        assertNotNull(trace);
        RequestTrace rTrace = RequestTraceHelper.toMaven("collect", trace);
        assertNotNull(rTrace);
        assertNotNull(rTrace.parent());
    }
    assertNotNull(node);
    assertEquals(6, node.getChildren().size());
}

