    suppressed.addSuppressed(new IllegalArgumentException("suppressed suppressed", new ArrayIndexOutOfBoundsException("suppressed suppressed cause")));
    Exception cause = new IllegalArgumentException("cause");
    cause.addSuppressed(suppressed);
    Exception throwable = new RuntimeException("top-level", cause);
    ByteArrayOutputStream output = new ByteArrayOutputStream();
    new MavenSimpleLogger("logger").writeThrowable(throwable, new PrintStream(output));
    String actual = output.toString(UTF_8);
    List<String> actualLines = Arrays.asList(actual.split(System.lineSeparator()));
    Class<?> testClass = testInfo.getTestClass().get();
    String testMethodName = testInfo.getTestMethod().get().getName();
    String testClassStackTraceLinePattern = "at " + testClass.getName() + "." + testMethodName + "\\(" + testClass.getSimpleName() + ".java:\\d+\\)";
    List<String> expectedLines = Arrays.asList("java.lang.RuntimeException: top-level", "    " + testClassStackTraceLinePattern, ">> stacktrace >>", "Caused by: java.lang.IllegalArgumentException: cause", "    " + testClassStackTraceLinePattern, ">> stacktrace >>", "    Suppressed: java.lang.IllegalStateException: suppressed", "        " + testClassStackTraceLinePattern, ">> stacktrace >>", "        Suppressed: java.lang.IllegalArgumentException: suppressed suppressed", "            " + testClassStackTraceLinePattern, ">> stacktrace >>", "        Caused by: java.lang.ArrayIndexOutOfBoundsException: suppressed suppressed cause", "            " + testClassStackTraceLinePattern, ">> stacktrace >>", "    Caused by: java.util.NoSuchElementException: cause of suppressed", "        " + testClassStackTraceLinePattern, ">> stacktrace >>");
    assertLinesMatch(expectedLines, actualLines);
}

