@Test
void testConsumerPomFiltersScopes() throws Exception {
    Path basedir = extractResources("/gh-11162-consumer-pom-scopes").toPath();
    Verifier verifier = newVerifier(basedir.toString());
    verifier.addCliArgument("install");
    verifier.execute();
    verifier.verifyErrorFreeLog();
    Path consumerPom = basedir.resolve(Paths.get("target", "project-local-repo", "org.apache.maven.its.gh11162", "consumer-pom-scopes-app", "1.0", "consumer-pom-scopes-app-1.0-consumer.pom"));
    assertTrue(Files.exists(consumerPom), "consumer pom not found at " + consumerPom);
    Model consumerPomModel;
    try (Reader r = Files.newBufferedReader(consumerPom)) {
        consumerPomModel = new MavenStaxReader().read(r);
    }
    long numDeps = consumerPomModel.getDependencies() != null ? consumerPomModel.getDependencies().size() : 0;
    assertEquals(2, numDeps, "Consumer POM should keep only compile and runtime dependencies");
    boolean hasCompile = consumerPomModel.getDependencies().stream().anyMatch(d -> "compile".equals(d.getScope()) && "compile-dep".equals(d.getArtifactId()));
    boolean hasRuntime = consumerPomModel.getDependencies().stream().anyMatch(d -> "runtime".equals(d.getScope()) && "runtime-dep".equals(d.getArtifactId()));
    assertTrue(hasCompile, "compile dependency should be present");
    assertTrue(hasRuntime, "runtime dependency should be present");
    long dropped = consumerPomModel.getDependencies().stream().map(d -> d.getScope()).filter(s -> !"compile".equals(s) && !"runtime".equals(s)).count();
    assertEquals(0, dropped, "All non compile/runtime scopes should be dropped in consumer POM");
}

