            assertEquals("true", props.getProperty(key + ".snapshots.enabled"));
            assertEquals("fail", props.getProperty(key + ".snapshots.checksumPolicy"));
            assertEquals("never", props.getProperty(key + ".snapshots.updatePolicy"));
        }
    }
}

