    Verifier verifier = newVerifier(testDir.getAbsolutePath());
    verifier.setAutoclean(false);
    verifier.deleteArtifacts("org.apache.maven.its.mng3284");
    verifier.filterFile("settings-template.xml", "settings.xml");
