         */
    verifier = newVerifier(testDir.getAbsolutePath());
    verifier.setAutoclean(false);
    verifier.deleteDirectory("mod-a/target");
    verifier.deleteDirectory("mod-b/target");
    verifier.addCliArgument("--settings");
