@Test
void testAfterPhaseExecutionOnFailure() throws Exception {
    File testDir = extractResources("/mng-5668-after-phase-execution");
    Verifier verifier = newVerifier(testDir.getAbsolutePath());
    verifier.setAutoclean(false);
    verifier.deleteDirectory("target");
    try {
        verifier.addCliArgument("-b");
        verifier.addCliArgument("concurrent");
        verifier.addCliArgument("verify");
        verifier.execute();
        fail("Build should have failed");
    } catch (VerificationException e) {
        // expected
    }
    // Verify that marker files were created in the expected order
    verifier.verifyFilePresent("target/before-verify.txt");
    verifier.verifyFilePresent("target/verify-failed.txt");
    verifier.verifyFilePresent("target/after-verify.txt");
    // Verify the execution order through timestamps
    long beforeTime = new File(testDir, "target/before-verify.txt").lastModified();
    long failTime = new File(testDir, "target/verify-failed.txt").lastModified();
    long afterTime = new File(testDir, "target/after-verify.txt").lastModified();
    assertTrue(beforeTime <= failTime);
    assertTrue(failTime <= afterTime);
}

@Test
public void testWithoutBuildConsumer() throws Exception {
    // prepare JavaAgent
    File testDir = extractResources("/mng-5669-read-poms-once");
    Verifier verifier = newVerifier(testDir.getAbsolutePath(), false);
    Map<String, String> filterProperties = Collections.singletonMap("${javaAgentJar}", verifier.getArtifactPath("org.apache.maven.its", "core-it-javaagent", "2.1-SNAPSHOT", "jar"));
    verifier.filterFile(".mvn/jvm.config", ".mvn/jvm.config", null, filterProperties);
    // pick up agent
    verifier.setForkJvm(true);
    verifier.setAutoclean(false);
    verifier.addCliArgument("-q");
    verifier.addCliArgument("-U");
    verifier.addCliArgument("-Dmaven.consumerpom=false");
    verifier.addCliArgument("verify");
    verifier.execute();
    List<String> logTxt = verifier.loadLines("log.txt");
    // count source items
    Map<String, Long> sourceMap = logTxt.stream().map(this::getSourceFromLogLine).filter(Objects::nonNull).collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));
    // find duplicates
    List<String> duplicates = sourceMap.entrySet().stream().filter(entry -> entry.getValue() > 1).map(Map.Entry::getKey).collect(Collectors.toList());
    assertTrue(duplicates.isEmpty(), "Duplicate items: " + String.join(System.lineSeparator(), duplicates));
}

