@Test
public void testitMNG6386UnicodeChars() throws Exception {
    String fileEncoding = System.getProperty("file.encoding");
    /*
         * Unfortunately, AbstractMavenIntegrationTestCase still uses JUnit 3.8 which does not have
         * Assume, so we cannot make assumptions and skip the test on non-compatible systems.
         */
    if (Os.isFamily(Os.FAMILY_WINDOWS) || "UTF-8".equalsIgnoreCase(fileEncoding) || "UTF8".equalsIgnoreCase(fileEncoding)) {
        File testDir = extractResources("/mng-6386-это по-русский").getCanonicalFile();
        Verifier verifier = newVerifier(testDir.getAbsolutePath());
        verifier.setAutoclean(false);
        verifier.deleteDirectory("target");
        verifier.setLogFileName("log-basic.txt");
        verifier.addCliArgument("validate");
        verifier.execute();
        verifier.verifyErrorFreeLog();
        Properties props = verifier.loadProperties("target/profile.properties");
        String pomProperty = props.getProperty("project.properties.pomProperty");
        // set via project
        assertEquals(testDir.toPath().toUri().toASCIIString(), pomProperty);
        // check that baseUri begins with file:///
        assertTrue(pomProperty.startsWith("file:///"));
        // check that baseUri ends with "это по-русский/", but properly URI-encoded
        // We need to make sure that either form NFC or NFD is accepted since HFS+ and APFS might use them
        assertTrue(pomProperty.endsWith("%D1%8D%D1%82%D0%BE%20%D0%BF%D0%BE-%D1%80%D1%83%D1%81%D1%81%D0%BA%D0%B8%D0%B9/") || pomProperty.endsWith("%D1%8D%D1%82%D0%BE%20%D0%BF%D0%BE-%D1%80%D1%83%D1%81%D1%81%D0%BA%D0%B8%D0%B8%CC%86/"));
    } else {
        System.out.println();
        System.out.println("[WARNING] Skipping MNG-6386 Unicode Chars Test on incompatible encoding: " + fileEncoding);
        System.out.println();
    }
}

/**
 * Check that the resulting output is
 * as expected for the root module and last
 * module in build but not for the intermediate
 * modules.
 *
 * @throws Exception in case of failure
 */
@Test
public void testitShouldPrintVersionAtTopAndAtBottom() throws Exception {
    File testDir = extractResources("/mng-6391-print-version");
    Verifier verifier = newVerifier(testDir.getAbsolutePath(), false);
    verifier.setAutoclean(false);
    verifier.setLogFileName("version-log.txt");
    verifier.addCliArgument("clean");
    verifier.execute();
    verifier.verifyErrorFreeLog();
    List<String> loadedLines = verifier.loadLines("version-log.txt");
    List<String> resultingLines = extractReactorBuildOrder(loadedLines);
    // We're expecting exactly four lines as result.
    assertEquals(5, resultingLines.size());
    // We expect those lines in the following exact order.
    // Maven 4.0.x has some code new code which takes care of the terminal width to adjust the output.
    // The number of dots can thus vary when running the tests.
    assertTrue(resultingLines.get(0).startsWith("[INFO] Reactor Summary for base-project 1.3.0-SNAPSHOT:"));
    assertTrue(resultingLines.get(1).matches("\\Q[INFO] base-project ............\\E\\.+\\Q SUCCESS [\\E.*"));
    assertTrue(resultingLines.get(2).matches("\\Q[INFO] module-1 ................\\E\\.+\\Q SUCCESS [\\E.*"));
    assertTrue(resultingLines.get(3).matches("\\Q[INFO] module-2 ................\\E\\.+\\Q SUCCESS [\\E.*"));
    assertTrue(resultingLines.get(4).matches("\\Q[INFO] module-3 ................\\E\\.+\\Q SUCCESS [\\E.*"));
    // We expect that line 1..4 have the same length
    int line1Length = resultingLines.get(1).length();
    assertEquals(line1Length, resultingLines.get(2).length());
    assertEquals(line1Length, resultingLines.get(3).length());
    assertEquals(line1Length, resultingLines.get(4).length());
}

